-- ORBIT V2 — Catálogo padrão de refrigeração e climatização.
--
-- Roteiros de atendimento, unidades do PMOC e o roteiro das visitas de RVT
-- vinham em branco: a empresa começava escrevendo do zero o que todo mundo
-- do segmento faz igual — preventiva, corretiva, instalação, higienização,
-- vistoria e laudo, refrigeração comercial, e o roteiro de cada parte do
-- sistema no PMOC (condensadora, evaporadora, dutos, fan-coil, self, chiller,
-- torre, quadro elétrico, renovação de ar).
--
-- ## Ponto de partida, não regra
--
-- Tudo aqui é cadastro comum da organização: editável, desativável e
-- removível pelas telas de sempre. A função **só acrescenta o que falta** —
-- pela chave, em qualquer versão e mesmo removida — então:
--
-- * o que a empresa já tinha com a mesma chave fica como está (os exemplos
--   `MANUTENCAO_PREVENTIVA`, `UNIDADE_CONDENSADORA`, `UNIDADE_EVAPORADORA`);
-- * o que ela editou não é sobrescrito;
-- * o que ela removeu não volta.
--
-- ## Uma fonte só
--
-- A mesma função roda aqui, para as organizações existentes, e no código:
-- cadastro de organização, restauração depois do expurgo por retenção e o
-- seed da conta de referência. SECURITY INVOKER: no runtime ela obedece à
-- RLS da transação que a chama — só escreve na organização do contexto.

CREATE OR REPLACE FUNCTION app_uuid_v7() RETURNS uuid
LANGUAGE sql VOLATILE SET search_path = pg_catalog, public AS $$
  SELECT (
    lpad(to_hex(floor(extract(epoch FROM clock_timestamp()) * 1000)::bigint), 12, '0') ||
    '7' || substr(replace(gen_random_uuid()::text, '-', ''), 14, 3) ||
    lpad(to_hex((8 + floor(random() * 4))::int), 1, '0') ||
    substr(replace(gen_random_uuid()::text, '-', ''), 18, 15)
  )::uuid
$$;

CREATE OR REPLACE FUNCTION app_seed_hvac_catalogs(p_organization_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY INVOKER SET search_path = pg_catalog, public AS $$
BEGIN
