    ('PMOC_SELF_CONTAINED', 'PMOC — self-contained', 'MAINTENANCE', 'Equipamento self-contained com condensação a ar ou a água.', '[{"key": "limpeza_filtros", "label": "Limpeza ou troca dos filtros", "type": "BOOLEAN", "required": true}, {"key": "limpeza_evaporador", "label": "Limpeza do evaporador", "type": "BOOLEAN", "required": true}, {"key": "limpeza_condensador", "label": "Limpeza do condensador", "type": "BOOLEAN", "required": true}, {"key": "bandeja_dreno", "label": "Bandeja limpa e dreno desobstruído", "type": "BOOLEAN", "required": true}, {"key": "correias_polias", "label": "Correias e polias: tensão e desgaste", "type": "SELECT", "required": false, "options": ["Adequadas", "Ajustadas", "Substituídas", "Não se aplica"]}, {"key": "conexoes_eletricas", "label": "Reaperto das conexões elétricas", "type": "BOOLEAN", "required": true}, {"key": "pressao_succao_psi", "label": "Pressão de sucção (psi)", "type": "NUMBER", "required": false}, {"key": "pressao_descarga_psi", "label": "Pressão de descarga (psi)", "type": "NUMBER", "required": false}, {"key": "corrente_compressor_a", "label": "Corrente do compressor (A)", "type": "NUMBER", "required": false}, {"key": "foto", "label": "Foto da unidade", "type": "PHOTO", "required": false}, {"key": "observacoes", "label": "Observações", "type": "TEXT", "required": false}]'::jsonb, 120),
    ('PMOC_CHILLER', 'PMOC — chiller', 'MAINTENANCE', 'Resfriador de líquido: pressões, temperaturas da água e elétrica.', '[{"key": "temperatura_entrada_agua_c", "label": "Temperatura de entrada da água gelada (°C)", "type": "NUMBER", "required": true}, {"key": "temperatura_saida_agua_c", "label": "Temperatura de saída da água gelada (°C)", "type": "NUMBER", "required": true}, {"key": "pressao_succao_psi", "label": "Pressão de sucção (psi)", "type": "NUMBER", "required": false}, {"key": "pressao_descarga_psi", "label": "Pressão de descarga (psi)", "type": "NUMBER", "required": false}, {"key": "corrente_compressores_a", "label": "Corrente dos compressores (A)", "type": "NUMBER", "required": false}, {"key": "nivel_oleo", "label": "Nível de óleo dos compressores", "type": "SELECT", "required": false, "options": ["Normal", "Baixo", "Não se aplica"]}, {"key": "limpeza_condensador", "label": "Limpeza do condensador", "type": "BOOLEAN", "required": true}, {"key": "alarmes_controlador", "label": "Alarmes no controlador", "type": "SELECT", "required": true, "options": ["Nenhum", "Sim — registrado nas observações"]}, {"key": "conexoes_eletricas", "label": "Reaperto das conexões elétricas", "type": "BOOLEAN", "required": false}, {"key": "foto", "label": "Foto do painel e do equipamento", "type": "PHOTO", "required": false}, {"key": "observacoes", "label": "Observações", "type": "TEXT", "required": false}]'::jsonb, 130),
    ('PMOC_TORRE', 'PMOC — torre de resfriamento', 'MAINTENANCE', 'Torre: bacia, enchimento, ventilador e tratamento químico da água.', '[{"key": "limpeza_bacia", "label": "Limpeza da bacia", "type": "BOOLEAN", "required": true}, {"key": "enchimento", "label": "Enchimento e bicos aspersores limpos", "type": "BOOLEAN", "required": true}, {"key": "ventilador_motor", "label": "Ventilador e motor sem ruído ou vibração", "type": "BOOLEAN", "required": true}, {"key": "tratamento_quimico", "label": "Tratamento químico da água em dia", "type": "SELECT", "required": true, "options": ["Sim", "Não", "Não verificado"]}, {"key": "boia_reposicao", "label": "Boia de reposição de água operando", "type": "BOOLEAN", "required": false}, {"key": "foto", "label": "Registro fotográfico", "type": "PHOTO", "required": false}, {"key": "observacoes", "label": "Observações", "type": "TEXT", "required": false}]'::jsonb, 140),
    ('PMOC_QUADRO_ELETRICO', 'PMOC — quadro elétrico e comandos', 'MAINTENANCE', 'Quadro de força e comando do sistema de climatização.', '[{"key": "reaperto_conexoes", "label": "Reaperto das conexões", "type": "BOOLEAN", "required": true}, {"key": "disjuntores_protecoes", "label": "Disjuntores e proteções adequados", "type": "BOOLEAN", "required": true}, {"key": "contatores_reles", "label": "Contatores e relés sem desgaste", "type": "BOOLEAN", "required": false}, {"key": "sinais_aquecimento", "label": "Sinais de aquecimento ou oxidação", "type": "SELECT", "required": true, "options": ["Não", "Sim — correção necessária"]}, {"key": "tensao_v", "label": "Tensão entre fases (V)", "type": "NUMBER", "required": false}, {"key": "foto", "label": "Foto do quadro", "type": "PHOTO", "required": false}, {"key": "observacoes", "label": "Observações", "type": "TEXT", "required": false}]'::jsonb, 150),
    ('PMOC_RENOVACAO_AR', 'PMOC — ventilação e renovação de ar', 'MAINTENANCE', 'Tomada de ar externo e renovação do ambiente climatizado.', '[{"key": "tomada_ar_externo", "label": "Tomada de ar externo desobstruída", "type": "BOOLEAN", "required": true}, {"key": "filtro_ar_externo", "label": "Filtro do ar externo limpo ou trocado", "type": "BOOLEAN", "required": true}, {"key": "vazao_renovacao_m3h", "label": "Vazão de ar de renovação medida (m³/h)", "type": "NUMBER", "required": false}, {"key": "ocupacao_ambiente", "label": "Ocupação do ambiente (pessoas)", "type": "NUMBER", "required": false}, {"key": "odor_umidade", "label": "Odor, mofo ou umidade aparente", "type": "SELECT", "required": true, "options": ["Não", "Sim — registrado nas observações"]}, {"key": "observacoes", "label": "Observações", "type": "TEXT", "required": false}]'::jsonb, 160)
  ) AS t(key, name, kind, description, items, ordem)
  WHERE NOT EXISTS (
    SELECT 1 FROM checklist_templates c
     WHERE c.organization_id = p_organization_id AND c.key = t.key
  )
  ORDER BY t.ordem;

  /* Unidades do PMOC, cada uma com o seu roteiro. */
  INSERT INTO pmoc_units (
    id, organization_id, key, name, description, checklist_template_id,
    sort_order, is_active, created_at, updated_at
  )
  SELECT app_uuid_v7(), p_organization_id, u.key, u.name, u.description,
         (SELECT c.id FROM checklist_templates c
           WHERE c.organization_id = p_organization_id AND c.key = u.roteiro
             AND c.deleted_at IS NULL
           ORDER BY c.version DESC LIMIT 1),
         u.ordem, true, now(), now()
  FROM (VALUES
    ('UNIDADE_CONDENSADORA', 'Unidade condensadora', 'Unidade externa do sistema split ou multi-split.', 'PMOC_CONDENSADORA', 10),
    ('UNIDADE_EVAPORADORA', 'Unidade evaporadora', 'Unidade interna: split, cassete, piso-teto ou duto.', 'PMOC_EVAPORADORA', 20),
    ('DUTOS_DIFUSORES', 'Dutos, grelhas e difusores', 'Rede de distribuição de ar do ambiente.', 'PMOC_DUTOS', 30),
    ('FAN_COIL', 'Fan-coil / climatizador', 'Unidade de tratamento de ar com água gelada ou expansão direta.', 'PMOC_FAN_COIL', 40),
    ('SELF_CONTAINED', 'Self-contained', 'Equipamento compacto com condensação a ar ou a água.', 'PMOC_SELF_CONTAINED', 50),
    ('CHILLER', 'Chiller', 'Resfriador de líquido da central de água gelada.', 'PMOC_CHILLER', 60),
    ('TORRE_RESFRIAMENTO', 'Torre de resfriamento', 'Torre da central de água gelada.', 'PMOC_TORRE', 70),
    ('QUADRO_ELETRICO', 'Quadro elétrico e comandos', 'Força e comando do sistema de climatização.', 'PMOC_QUADRO_ELETRICO', 80),
    ('RENOVACAO_AR', 'Ventilação e renovação de ar', 'Tomada de ar externo e renovação do ambiente.', 'PMOC_RENOVACAO_AR', 90)
  ) AS u(key, name, description, roteiro, ordem)
  ON CONFLICT (organization_id, key) DO NOTHING;

  /* Quadrimestral: comum em contrato de manutenção, faltava entre os ritmos. */
  INSERT INTO rvt_maintenance_types (
    id, organization_id, key, label, interval_days, interval_months,
    sort_order, created_at, updated_at
  )
  VALUES (app_uuid_v7(), p_organization_id, 'FOUR_MONTHLY', 'Quadrimestral',
          NULL, 4, 55, now(), now())
  ON CONFLICT (organization_id, key) DO NOTHING;

  /* As visitas de RVT seguem a preventiva, onde ainda não há roteiro. */
  UPDATE rvt_maintenance_types r
     SET checklist_template_id = p.id, updated_at = now()
    FROM (SELECT c.id FROM checklist_templates c
           WHERE c.organization_id = p_organization_id
             AND c.key = 'MANUTENCAO_PREVENTIVA' AND c.deleted_at IS NULL
           ORDER BY c.version DESC LIMIT 1) p
   WHERE r.organization_id = p_organization_id
     AND r.checklist_template_id IS NULL
     AND r.deleted_at IS NULL;
END;
$$;

REVOKE ALL ON FUNCTION app_uuid_v7() FROM PUBLIC;
REVOKE ALL ON FUNCTION app_seed_hvac_catalogs(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_uuid_v7() TO orbit_app;
GRANT EXECUTE ON FUNCTION app_seed_hvac_catalogs(uuid) TO orbit_app;

-- As organizações que já existem.
SELECT app_seed_hvac_catalogs(o.id)
  FROM organizations o
 WHERE o.deleted_at IS NULL;
